// Fonction qui retourne un impl Trait (type concret à l'avance)
fn function1() -> Box<dyn Animal> {

    // Création d'un objet Sheep
    let sheep = Sheep {};

    // Retour du trait object de type Box<dyn Animal>
    return Box::new(sheep);
